<script setup lang="ts">import {ref,computed,watch} from 'vue';import type {Corpus,CorpusVersion,Document,User} from '../types/domain';import {corpusApi} from '../api/corpora';import {useAsync} from '../hooks/useAsync';import {date} from '../utils/format';import PageTitle from '../components/common/PageTitle.vue';import Table from '../components/common/Table.vue';import Notice from '../components/common/Notice.vue';import Badge from '../components/common/Badge.vue';const props=defineProps<{corpora:Corpus[];documents:Document[];versions:CorpusVersion[];whitelist:string[];user:User;reload:()=>Promise<any>}>();const corpusId=ref(0),show=ref(false),name=ref(''),raw=ref(''),edit=ref<Document|null>(null),title=ref(''),text=ref('');const active=computed(()=>corpusId.value||props.corpora[0]?.id),docs=computed(()=>props.documents.filter(d=>d.corpus_id===active.value));const corpusVersions=computed(()=>props.versions.filter(v=>v.corpus_id===active.value).sort((a,b)=>b.version_no-a.version_no));const receiving=computed(()=>corpusVersions.value.filter(v=>v.status==='receiving'));const vno=ref(0),vtotal=ref(2),shardVersion=ref(0),shardIndex=ref(0),shardRaw=ref('');const {task,act}=useAsync();watch(active,()=>{shardVersion.value=0});watch(corpusVersions,vs=>{vno.value=vs.length?vs[0].version_no+1:1},{immediate:true});watch([receiving,shardVersion],()=>{if(shardVersion.value&&!receiving.value.some(v=>v.id===shardVersion.value))shardVersion.value=0;const v=receiving.value.find(x=>x.id===shardVersion.value);if(v&&v.missing_shards.length)shardIndex.value=v.missing_shards[0]},{immediate:true});function choose(d:Document){edit.value=d;title.value=d.title;text.value=d.tokens_text}async function submit(){await act(async()=>{await corpusApi.create({name:name.value,filename:name.value+'.json',description:'编辑导入的已分词摘要',documents:JSON.parse(raw.value)});await props.reload();show.value=false},'分词语料已导入，首版即刻生效')};async function submitVersion(){await act(async()=>{await corpusApi.createVersion(active.value,{version_no:vno.value,shard_total:vtotal.value});await props.reload()},'版本已登记，可分片续传；收齐前当前版本继续生效')};async function submitShard(){await act(async()=>{await corpusApi.uploadShard(shardVersion.value,{shard_index:shardIndex.value,documents:JSON.parse(shardRaw.value)});await props.reload();shardRaw.value=''},'分片已接收；重传同内容分片不会重复展签')};</script><template><PageTitle index="02 / TOKEN CORPUS" title="词已经分好，口径仍要核对。" description="只按空白切词，精确匹配固定50词白名单；不做中文自动分词。白名单后或min_df后空词文档单独记录，不伪造主题得分。"><button v-if="user.role!=='viewer'" @click="show=!show">导入分词语料 ↗</button></PageTitle><Notice :error="task.error" :message="task.message"/><form class="editor" v-if="show" @submit.prevent="submit"><h2>导入5–1000份JSON文档（新语料首版）</h2><label>语料名称<input v-model="name" required maxlength="100"/></label><label>文档JSON数组<textarea rows="6" v-model="raw" required placeholder='[{"reference":"DOC-001","title":"展签摘要","tokens_text":"陶土 材料 工艺"},…]'/></label><button class="primary" :disabled="task.busy">校验并导入</button></form><div class="source-selector"><label>当前语料<select v-model="corpusId"><option :value="0" v-if="corpora[0]">默认 / {{corpora[0].name}}</option><option v-for="c in corpora" :key="c.id" :value="c.id">{{c.name}} / {{c.document_count}}篇</option></select></label><p>{{corpora.find(c=>c.id===active)?.description}}<br/>{{corpora.find(c=>c.id===active)?.filename}}<br/>实际生效版本：{{corpora.find(c=>c.id===active)?.active_version_no?'v'+corpora.find(c=>c.id===active)?.active_version_no:'暂无（等待收齐）'}}</p></div><div class="section-title"><h2>版本与分片</h2><small>收齐后整包替换；缺席展签随新版移除；研究只读生效版本</small></div><Table :headers="['版号','状态','分片进度','缺片序号','展签数','登记时间']"><tr v-for="v in corpusVersions" :key="v.id" :class="{current:v.status==='active'}"><td><small>VERSION</small><strong>v{{v.version_no}}<template v-if="v.status==='active'"> · 实际生效</template></strong></td><td><Badge :status="v.status"/></td><td>{{v.received_shards.length}} / {{v.shard_total}}</td><td class="mono">{{v.missing_shards.length?'#'+v.missing_shards.join(' #'):'—'}}</td><td>{{v.document_count}}</td><td class="mono">{{date(v.created_at)}}</td></tr></Table><div class="version-forms" v-if="user.role!=='viewer'&&corpora.length"><form class="editor" @submit.prevent="submitVersion"><h2>登记新版本</h2><p>递增版号加分片总数交付修订；分片可乱序、可重传，收齐前上一完整版本继续生效。同片内容冲突将整版隔离。</p><div class="form-grid"><label>版号（递增）<input type="number" v-model.number="vno" min="1" max="1000000" step="1" required placeholder="如 2"/></label><label>分片总数<input type="number" v-model.number="vtotal" min="1" max="64" step="1" required/></label></div><button class="primary" :disabled="task.busy">登记版本</button></form><form class="editor" @submit.prevent="submitShard"><h2>续传分片</h2><p>选择未齐版本续传；缺片序号已定位。重传同内容分片幂等，不重复展签。</p><label>未齐版本<select v-model.number="shardVersion" required><option :value="0" disabled>选择接收中版本</option><option v-for="v in receiving" :key="v.id" :value="v.id">v{{v.version_no}} · 已收{{v.received_shards.length}}/{{v.shard_total}} · 缺 #{{v.missing_shards.join(' #')}}</option></select></label><div class="form-grid"><label>分片序号<input type="number" v-model.number="shardIndex" min="0" max="63" step="1" required/></label></div><label>分片文档JSON数组<textarea rows="5" v-model="shardRaw" required placeholder='[{"reference":"ZC-0361","title":"展签摘要","tokens_text":"陶土 材料 工艺"},…]'/></label><button class="primary" :disabled="task.busy||!shardVersion">上传分片</button></form></div><div class="whitelist"><small>FIXED WHITELIST / 精确匹配</small><p>{{whitelist.join(' · ')}}</p></div><form v-if="edit" class="editor" @submit.prevent="act(async()=>{await corpusApi.edit(edit!.id,{title,tokens_text:text});await reload();edit=null},'分词文档已修订，历史运行保持原结果')"><h2>修订 {{edit.reference}}</h2><label>标题<input v-model="title" maxlength="120" required/></label><label>已分词文本<textarea rows="4" v-model="text" maxlength="10000"/></label><button class="primary" :disabled="task.busy">保存修订</button></form><div class="section-title"><h2>原始文档样本</h2><small>展示前40 / 总{{docs.length}}，计算用全部</small></div><Table :headers="['文档 / 标题','空白分词摘要','']"><tr v-for="d in docs.slice(0,40)" :key="d.id"><td><small>{{d.reference}}</small><strong>{{d.title}}</strong></td><td class="token-text">{{d.tokens_text||'（空词文档）'}}</td><td><button v-if="user.role!=='viewer'" class="text-button" @click="choose(d)">编辑分词 ↗</button></td></tr></Table></template>
